ST.xhtml:p:
IF fire AND (NOT Busy) THEN
    IF (pos_target > 100) OR (pos_target < 0) THEN
        Done := TRUE;
    ELSIF ABS(INT_TO_REAL(pos_target) - pos) > 0.499 THEN
        tgt := INT_TO_REAL(pos_target);
        Busy := TRUE;
        Done := FALSE;
    ELSE
        Done := TRUE;
    END_IF;
END_IF;

IF hold_req THEN
    IF vel > 0.0 THEN vel := MAX(0.0, vel - Accel * SCAN_T);
    ELSIF vel < 0.0 THEN vel := MIN(0.0, vel + Accel * SCAN_T);
    END_IF;
ELSIF Busy THEN
    dist := tgt - pos;
    stop_d := (vel * vel) / (2.0 * Accel);
    IF ABS(dist) <= stop_d THEN
        IF dist >= 0.0 THEN vel := MAX(0.0, vel - Accel * SCAN_T);
        ELSE vel := MIN(0.0, vel + Accel * SCAN_T);
        END_IF;
        IF (vel = 0.0) AND (ABS(dist) <= Poswin) THEN
            pos := tgt;
            Busy := FALSE;
            Done := TRUE;
        END_IF;
    ELSE
        IF dist > 0.0 THEN vel := MIN(Vmax, vel + Accel * SCAN_T);
        ELSE vel := MAX(-Vmax, vel + Accel * SCAN_T);
        END_IF;
    END_IF;
END_IF;

pos := pos + vel * SCAN_T;
Setpoint := REAL_TO_INT(pos);

cmd := cw AND 16#000F;

IF (state = 7) AND ((cw AND 16#0080) <> 0) THEN
    state := 1;
END_IF;

CASE state OF
    1: IF cmd = 16#06 THEN state := 2; END_IF;
    2: IF cmd = 16#07 THEN state := 3;
       ELSIF cmd = 16#0F THEN state := 4;
       ELSIF cmd = 16#00 THEN state := 1;
       END_IF;
    3: IF cmd = 16#0F THEN state := 4;
       ELSIF cmd = 16#06 THEN state := 2;
       ELSIF cmd = 16#00 THEN state := 1;
       ELSIF cmd = 16#02 THEN state := 5;
       END_IF;
    4: IF cmd = 16#07 THEN state := 3;
       ELSIF cmd = 16#06 THEN state := 2;
       ELSIF cmd = 16#00 THEN state := 1;
       ELSIF cmd = 16#02 THEN state := 5;
       END_IF;
    5: IF v_out = 0.0 THEN
           IF cmd = 16#0F THEN state := 4;
           ELSIF cmd = 16#06 THEN state := 2;
           ELSIF cmd = 16#00 THEN state := 1;
           END_IF;
       END_IF;
    6: IF v_out = 0.0 THEN state := 7; END_IF;
END_CASE;

IF (state >= 4) AND (state <= 6) THEN
    v_ff := INT_TO_REAL(Setpoint - sp_prev) / SCAN_T;
    pos_err := INT_TO_REAL(Setpoint) - INT_TO_REAL(pos_fb);
    v_out := v_ff + KP * pos_err;
    IF v_out > Vmax THEN v_out := Vmax; END_IF;
    IF v_out < -Vmax THEN v_out := -Vmax; END_IF;
    IF (v_ff = 0.0) AND (ABS(pos_err) <= 1.5) THEN
        v_out := 0.0;
    END_IF;
ELSIF state = 5 THEN
    IF v_out > 0.0 THEN v_out := MAX(0.0, v_out - QS_DECEL * SCAN_T);
    ELSIF v_out < 0.0 THEN v_out := MIN(0.0, v_out + QS_DECEL * SCAN_T);
    END_IF;
ELSE
    v_out := 0.0;
END_IF;

sp_prev := Setpoint;
v_cmd := REAL_TO_INT(v_out);

sw := 0;
CASE state OF
    1: sw := 16#0040;
    2: sw := 16#0031;
    3: sw := 16#0033;
    4: sw := 16#0037;
    5: sw := 16#0014;
    6: sw := 16#0008;
    7: sw := 16#0018;
END_CASE;
IF state = 4 THEN
    IF (ABS(pos_err) <= 2.0) AND (v_ff = 0.0) THEN
        sw := sw OR 16#0400;
    END_IF;
END_IF;

IF Enable AND (pstep = 4) AND ((sw AND 16#0004) = 0) AND ((sw AND 16#0008) = 0) THEN
    pstep := 0;
END_IF;
IF Enable THEN
    CASE pstep OF
        0: cw := (cw AND 16#00F0) OR 16#0006; pstep := 1;
        1: IF (sw AND 16#0001) <> 0 THEN cw := (cw AND 16#00F0) OR 16#0007; pstep := 2; END_IF;
        2: IF (sw AND 16#0002) <> 0 THEN cw := (cw AND 16#00F0) OR 16#000F; pstep := 3; END_IF;
        3: IF (sw AND 16#0004) <> 0 THEN pstep := 4; END_IF;
    END_CASE;
ELSE
    cw := (cw AND 16#00F0) OR 16#0006;
    pstep := 0;
END_IF;
Status := (sw AND 16#0004) <> 0;

IF fire AND (NOT edge_rs) THEN
    busy := TRUE;
END_IF;
edge_rs := fire;
IF busy THEN
    IF (sw AND 16#0008) <> 0 THEN
        cw := cw OR 16#0080;
    ELSE
        cw := cw AND 16#FF7F;
        busy := FALSE;
    END_IF;
END_IF;
Done := (NOT busy) AND ((sw AND 16#0008) = 0) AND (NOT fire);

IF fire THEN
    cw := (cw AND 16#00F0) OR 16#0002;
    Done := FALSE;
ELSE
    Done := TRUE;
END_IF;

IF fire AND (NOT edge_ma) THEN
    interp_exe := TRUE;
END_IF;
edge_ma := fire;
Done := (NOT interp_exe);
Busy := interp_exe;

IF fire AND (NOT edge_hm) THEN
    home_exe := TRUE;
END_IF;
edge_hm := fire;
Done := (NOT home_exe);

IF JogForward AND (jog_pos < 97) THEN
    jog_pos := jog_pos + 1;
ELSIF JogBackward AND (jog_pos > 3) THEN
    jog_pos := jog_pos - 1;
END_IF;
Busy := JogForward OR JogBackward;

(* ---- program identity ---- *)
prog_id := 3;

(* ---- pen state: z_fb<=1 means pen on paper ---- *)
pen_down := (z_fb <= 1);

(* ---- sample drive status words ---- *)
x_swv := dv_x.sw;
y_swv := dv_y.sw;
z_swv := dv_z.sw;
x_sw := WORD_TO_INT(x_swv);
y_sw := WORD_TO_INT(y_swv);
z_sw := WORD_TO_INT(z_swv);

(* C4: any drive fault ---- *)
fault_any := ((x_swv AND 16#0008) <> 0) OR ((y_swv AND 16#0008) <> 0) OR ((z_swv AND 16#0008) <> 0);

(* ---- power / reset / quickstop ---- *)
pwr_x(Enable := run AND (NOT quickstop), cw := x_cw, sw := x_swv);
pwr_y(Enable := run AND (NOT quickstop), cw := y_cw, sw := y_swv);
pwr_z(Enable := run AND (NOT quickstop), cw := z_cw, sw := z_swv);
rs_x(fire := cmd_reset, cw := x_cw, sw := x_swv);
rs_y(fire := cmd_reset, cw := y_cw, sw := y_swv);
rs_z(fire := cmd_reset, cw := z_cw, sw := z_swv);
st_x(fire := quickstop, cw := x_cw);
st_y(fire := quickstop, cw := y_cw);
st_z(fire := quickstop, cw := z_cw);

(* C1/C3/C4: quickstop / not run / fault aborts sequence, plot_done off ---- *)
IF (quickstop OR fault_any OR (NOT run)) AND (pl_step <> 0) THEN
    pl_step := 0;
    go_x_exe := FALSE;
    go_y_exe := FALSE;
    go_z_exe := FALSE;
    hm_z_exe := FALSE;
    ang := -1.5708;
END_IF;
IF quickstop OR fault_any OR (NOT run) THEN
    plot_done := FALSE;
END_IF;

(* ---- manual / home triggers (C2: pen interlock on manual only) ---- *)
go_x(fire := cmd_go AND (NOT pen_down) AND run AND (pl_step = 0), Position := x_sp, interp_exe := go_x_exe);
go_y(fire := cmd_go AND (NOT pen_down) AND run AND (pl_step = 0), Position := y_sp, interp_exe := go_y_exe);
go_z(fire := cmd_go AND run AND (pl_step = 0), Position := z_sp, interp_exe := go_z_exe);
hm_z(fire := cmd_home AND run AND (pl_step = 0), home_exe := hm_z_exe);
jg_x(JogForward := jog_fwd AND (NOT pen_down) AND run, JogBackward := jog_rev AND (NOT pen_down) AND run, jog_pos := x_jog_pos);

(* ---- circle sequencer: level-held triggers, steps only change targets ---- *)
(* 0=idle 1=pen up 2=XY to start(50,25) 3=pen down 4=arc full turn 5=pen up 6=back to center *)
CASE pl_step OF
    0: IF run AND cmd_draw AND (NOT quickstop) AND (NOT fault_any) AND all_oe THEN
           ang := -1.5708;
           go_x_exe := FALSE;
           go_y_exe := FALSE;
           go_z_exe := FALSE;
           hm_z_exe := FALSE;
           pl_step := 1;
       END_IF;
    1: tz := 10;
       go_z_exe := TRUE;
    2: tx := 50;
       ty := 25;
       go_x_exe := TRUE;
       go_y_exe := TRUE;
    3: tz := 0;
       go_z_exe := TRUE;
    4: ang := ang + 0.032;
       tx := 50 + REAL_TO_INT(25.0 * COS(ang));
       ty := 50 + REAL_TO_INT(25.0 * SIN(ang));
       IF ang >= 4.7124 THEN
           ang := 4.7124;
           pl_step := 5;
       END_IF;
    5: tz := 10;
       go_z_exe := TRUE;
    6: tx := 50;
       ty := 50;
       go_x_exe := TRUE;
       go_y_exe := TRUE;
END_CASE;

(* ---- step advance conditions ---- *)
IF pl_step = 1 THEN
    IF ix_z.Done AND (NOT ix_z.Busy) AND (z_fb >= 10) THEN
        go_z_exe := FALSE;
        pl_step := 2;
    END_IF;
END_IF;
IF pl_step = 2 THEN
    IF ix_x.Done AND ix_y.Done AND (NOT ix_x.Busy) AND (NOT ix_y.Busy) AND (ABS(x_fb - 50) <= 2) AND (ABS(y_fb - 25) <= 2) THEN
        go_x_exe := FALSE;
        go_y_exe := FALSE;
        ang := -1.5708;
        pl_step := 3;
    END_IF;
END_IF;
IF pl_step = 3 THEN
    IF ix_z.Done AND (NOT ix_z.Busy) AND (z_fb <= 1) THEN
        go_z_exe := FALSE;
        ang := -1.5708;
        pl_step := 4;
    END_IF;
END_IF;
IF pl_step = 5 THEN
    IF ix_z.Done AND (NOT ix_z.Busy) AND (z_fb >= 10) THEN
        go_z_exe := FALSE;
        pl_step := 6;
    END_IF;
END_IF;
IF pl_step = 6 THEN
    IF ix_x.Done AND ix_y.Done AND (NOT ix_x.Busy) AND (NOT ix_y.Busy) AND (ABS(x_fb - 50) <= 2) AND (ABS(y_fb - 50) <= 2) THEN
        go_x_exe := FALSE;
        go_y_exe := FALSE;
        plot_done := TRUE;
        pl_step := 0;
    END_IF;
END_IF;

(* ---- interp target routing ---- *)
IF jg_x.Busy THEN
    x_interp := x_jog_pos;
ELSIF pl_step >= 2 THEN
    x_interp := tx;
ELSE
    x_interp := x_sp;
END_IF;

IF pl_step >= 2 THEN
    y_interp := ty;
ELSE
    y_interp := y_sp;
END_IF;

IF (pl_step >= 1) OR hm_z_exe THEN
    z_interp := tz;
ELSE
    z_interp := z_sp;
END_IF;

(* ---- interp engines: continuous tracking, level-held fire ---- *)
ix_x(fire := go_x_exe, pos_target := x_interp, hold_req := quickstop OR (NOT run) OR fault_any, Vmax := 60.0, Accel := 80.0, Poswin := 0.5);
ix_y(fire := go_y_exe, pos_target := y_interp, hold_req := quickstop OR (NOT run) OR fault_any, Vmax := 60.0, Accel := 80.0, Poswin := 0.5);
ix_z(fire := go_z_exe OR hm_z_exe, pos_target := z_interp, hold_req := quickstop OR (NOT run) OR fault_any, Vmax := 20.0, Accel := 40.0, Poswin := 0.4);

(* ---- after INTERP done at idle step, use its setpoint as drive input ---- *)
IF (pl_step = 0) AND (NOT jg_x.Busy) THEN
    x_interp := ix_x.Setpoint;
END_IF;
IF pl_step = 0 THEN
    y_interp := ix_y.Setpoint;
END_IF;
IF (pl_step = 0) AND (NOT go_z_exe) AND (NOT hm_z_exe) THEN
    z_interp := ix_z.Setpoint;
END_IF;

(* ---- clear trigger lines at idle once done ---- *)
IF ix_x.Done AND (NOT ix_x.Busy) AND (pl_step = 0) AND (NOT cmd_go) THEN
    go_x_exe := FALSE;
END_IF;
IF ix_y.Done AND (NOT ix_y.Busy) AND (pl_step = 0) AND (NOT cmd_go) THEN
    go_y_exe := FALSE;
END_IF;
IF ix_z.Done AND (NOT ix_z.Busy) AND (pl_step = 0) AND (NOT cmd_go) AND (NOT cmd_home) THEN
    go_z_exe := FALSE;
    hm_z_exe := FALSE;
END_IF;

(* ---- jog overrides X setpoint ---- *)
IF jg_x.Busy THEN
    x_interp := x_jog_pos;
END_IF;

(* ---- drives follow setpoint, closed position loop ---- *)
dv_x(cw := x_cw, Setpoint := x_interp, pos_fb := x_fb, Vmax := 120.0);
x_v := dv_x.v_cmd;
dv_y(cw := y_cw, Setpoint := y_interp, pos_fb := y_fb, Vmax := 120.0);
y_v := dv_y.v_cmd;
dv_z(cw := z_cw, Setpoint := z_interp, pos_fb := z_fb, Vmax := 20.0);
z_v := dv_z.v_cmd;

(* ---- application status ---- *)
all_oe := pwr_x.Status AND pwr_y.Status AND pwr_z.Status;
move_done := go_x.Done AND go_y.Done AND go_z.Done AND (pl_step = 0);
any_moving := (x_v <> 0) OR (y_v <> 0) OR (z_v <> 0);
